HTML = """<!doctype html><html lang=zh><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>TechBridge 拜访控制台</title><style>body{font:16px system-ui;background:#eef3f8;color:#13283c;max-width:1080px;margin:auto;padding:24px}section{background:white;padding:24px;margin:18px 0;border-radius:16px}button,input{padding:12px;margin:6px;border:1px solid #ccd5df;border-radius:7px}button{cursor:pointer;background:#e0efe9}pre{white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:#64748b}</style><h1>TechBridge · 拜访控制台</h1><p class=muted>本地 Qwen ASR → GPT OSS 20B → 文本归档 → 原音频清理。CRM变更待确认。</p><section><h2>本次客户拜访</h2><input id=customer placeholder='客户公司'><input id=focus placeholder='拜访目标'><button id=create>创建拜访</button><p id=visit>未开始</p></section><section><h2>设备接力</h2><p id=owner>读取中</p><button id=mac>由Mac接力监听</button><button id=stop>停止Mac监听</button><p class=muted>先停止原设备再授权新设备。手机/手表被系统终止、Mac睡眠或网络断开时不能保证无缝接力。</p></section><section><h2>整合与待确认任务</h2><pre id=summary>暂无整合结果</pre><button id=export>下载本次拜访证据 JSON</button></section><section><h2>录音、转写、整理</h2><div id=clips></div></section><script>
let current;const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!r.ok)throw Error('HTTP '+r.status);return r.json()}
async function refresh(){try{current=await api('/api/visit-console');document.querySelector('#visit').textContent=current.visit?current.visit.customer+' · '+current.visit.focus:'未开始拜访';document.querySelector('#owner').textContent='监听设备：'+(current.lease.owner||'无')+'；接力目标：'+(current.lease.requested||'无');document.querySelector('#summary').textContent=current.visit?.summary_json?JSON.stringify(JSON.parse(current.visit.summary_json),null,2):'暂无整合结果';document.querySelector('#clips').innerHTML=current.clips.map(c=>'<article><h3>'+esc(c.title||'#'+c.id)+'</h3><p>'+esc(c.transcription_status)+' / '+esc(c.enrichment_status)+' / 音频 '+esc(c.audio_status)+'</p><pre>'+esc(c.transcript)+'</pre><pre>'+esc(c.summary)+'</pre></article>').join('')||'尚无片段'}catch(e){document.querySelector('#owner').textContent='连接失败：'+e.message}}
document.querySelector('#create').onclick=async()=>{try{await api('/api/visit-create',{customer:document.querySelector('#customer').value,focus:document.querySelector('#focus').value});await refresh()}catch(e){alert(e.message)}};
document.querySelector('#mac').onclick=async()=>{await api('/api/capture-request',{owner:'mac'});await refresh()};document.querySelector('#stop').onclick=async()=>{await api('/api/capture-request',{owner:'stopped'});await refresh()};
document.querySelector('#export').onclick=()=>{if(!current?.visit)return;const u=URL.createObjectURL(new Blob([JSON.stringify({...current,crmStatus:'pending_human_confirmation'},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='visit-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};refresh();setInterval(refresh,5000);
</script></html>"""
